export function decide(a,b,c) {
  if ((a && b) || !c) return 1;
  return 0;
}

function choose(a, b, c) {
  if (!(a || b) && c) return 'yes';
  return 'no';
}

export function nested(a: boolean, b: boolean) {
  if (a) {
    if (b || a) return 1;
  }
  return 0;
}

export const View = ({a, b}: {a: boolean; b: boolean}) => {
  if (a && b) return <div>yes</div>;
  return <div>no</div>;
};

export function choose(a, b) {
  return a && b ? 'yes' : 'no';
}

export function count(limit, enabled) {
  let value = 0;
  while (value < limit && enabled) value++;
  return value;
}

export function count(limit, enabled) {
  let value = 0;
  do value++; while (value < limit && enabled);
  return value;
}

export function count(limit, enabled) {
  let value = 0;
  for (; value < limit && enabled; value++) work(value);
  return value;
}
